#!/usr/bin/env python3
"""Render Gateway API/control-plane evidence without converting blocks to scores."""
import argparse,json,os,re
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('data',type=Path);p.add_argument('--output',type=Path,required=True);p.add_argument('--review',type=Path,required=True);a=p.parse_args()
review=json.loads(a.review.read_text());assert review['infrastructure_valid'] and review['all_three_passes_reviewed']
review_link=Path(os.path.relpath(a.review,a.output.parent)).as_posix()
attribution=json.loads((a.data.parent.parent/'evidence/qualification/final-facts/kubernetes-attribution.json').read_text())
large_counts=[]
for row in sorted(attribution['scale_diagnostics'],key=lambda x:x['pass']):
 if row['routes']==5000:
  values={int(re.search(r'\((\d+),',m).group(1)) for m in row['filter_guard_messages_from_replacement_pods']}
  assert len(values)==1
  large_counts.append(next(iter(values)))
large_counts_text=', '.join(f'{x:,}' for x in large_counts)
def read(n):return json.loads((a.data/(n+'.json')).read_text())
scale=read('scale-rows');recovery=read('recovery-rows');static=read('static-address-rows');blocks=read('setup-blocks')
scale_summary=read('scale-summary');recovery_summary=read('recovery-summary')
assert len(scale_summary)==8 and len(recovery_summary)==4
assert all(x['three_complete_passes'] for x in scale_summary+recovery_summary)
assert len(scale)==24 and len(recovery)==12 and len(static)==6 and len(blocks)==3
assert all(x['cleanup_complete'] for x in static)
labels={'agentgateway':'Agentgateway v1.6.0','praxis-release':'Praxis core v0.5.2','praxis':'Praxis core v0.5.2','praxis-nightly':'Praxis core nightly-20261002'}
def f(v):return 'Not observed' if v is None else f'{v:.3f}'
def interval(g,key):
 m=g['metrics'].get(key)
 return 'Not observed' if m is None else f"{m['arithmetic_mean']:.3f} [{m['min']:.3f}–{m['max']:.3f}]"
def recovery_cell(row):
 return 'No failures observed' if row['post_mutation_failed_requests']==0 else f(row['observed_recovery_after_mutation_seconds'])
lines=['# Gateway API: correctness, configuration scale and recovery','', 'These are separate evidence families. HTTP throughput does not establish feature coverage, and a successful status condition does not by itself establish that updated routes serve the intended response.','', '## Retained extended-conformance campaign','', 'The October 2 campaign used the same agentgateway v1.6.0 and Praxis core image digests, but upstream conformance v1.5.1. Both release implementations passed all 33 selected HTTP core cases in each repetition. Across 107 selected cases, the recorded results were 106/107 for agentgateway and 52/107 for Praxis core v0.5.2. The selected cases include core and extended HTTP/Gateway behavior, gRPC and TLS routes; counts are test cases, not percentages of the specification or official certification.','', 'Use the [release comparison](../../2026-10-02-gateway-extended/reports/release-comparison.md) for all retained per-case outcomes and the [nightly compatibility report](../../2026-10-02-gateway-extended/reports/nightly-compatibility.md) for its setup block. Do not manufacture a new 107-case score by combining suite versions.','', '## Corrected static-address follow-up','', 'The old `GatewayStaticAddresses` test asserted an earlier status snapshot. Agentgateway release CI explicitly ran and passed the corrected test; it was not skipped. This campaign runs only that case from conformance v1.6.1, source `8bb74df00e56ec8f944d48c25e6c1c9c2f6848e3`, on GCE for both runnable releases. Product images remain unchanged.','', '| Implementation | Repetition 1 | Repetition 2 | Repetition 3 |','| --- | --- | --- | --- |']
for treatment in ['agentgateway','praxis']:
 rs=sorted([x for x in static if x['treatment']==treatment],key=lambda x:x['pass']);assert [x['pass'] for x in rs]==[1,2,3]
 lines.append('| '+labels[treatment]+' | '+' | '.join('PASS' if x['passed'] and x['exit']==0 else 'FAIL' if x['failed'] else 'Harness outcome: '+str(x['exit']) for x in rs)+' |')
lines+=['', 'The [prior CI investigation](../../2026-10-02-gateway-extended/reports/agentgateway-static-address-follow-up.md) remains the authority for the original discrepancy. Fresh follow-up rows and artifact paths are in [static-address-rows.json](data/static-address-rows.json). Original v1.5.1 failures remain unchanged.','', 'The [pinned test](https://github.com/kubernetes-sigs/gateway-api/blob/8bb74df00e56ec8f944d48c25e6c1c9c2f6848e3/conformance/tests/gateway-static-addresses.go) checks address validation, conditions, listener status and address assignment. It does not send HTTP traffic to the assigned address. This campaign uses MetalLB for allocation/status and private NodePort for measured HTTP; it does not demonstrate external VIP reachability.', '', '## Route create/update scenarios','', 'ClusterLoader2 submits 1,000 or 5,000 hostname-bearing HTTPRoutes at 100 writes/sec. Each adds a generation-specific response header. The observer checks current-generation Accepted/ResolvedRefs status and then verifies every route through traffic. Its bounded observation window is 300 seconds after submission; times below include submission. “Not observed” is censored, not zero.','', '| Implementation | Pass | Routes | Mutation marker | Fully verified | Current status count at end | Sample passing at end | Full-traffic completion seconds |','| --- | ---: | ---: | --- | --- | ---: | --- | ---: |']
# Keep the complete per-pass table after a compact three-pass summary.
per_pass_heading=lines[-2:];lines=lines[:-2]
lines+=['| Implementation | Routes | Mutation | Fully verified runs | Completion seconds: mean [min–max] |','| --- | ---: | --- | ---: | ---: |']
for g in sorted(scale_summary,key=lambda x:(x['treatment'],x['count'],x['marker'])):
 lines.append('| '+' | '.join([labels[g['treatment']],str(g['count']),g['marker'],str(g['converged_passes'])+'/3',interval(g,'all_route_traffic_verified_seconds')])+' |')
lines+=['', '### Every route mutation', '', *per_pass_heading]
for x in sorted(scale,key=lambda x:(x['treatment'],x['pass'],x['count'],x['marker'])):
 lines.append('| '+' | '.join([labels[x['treatment']],str(x['pass']),str(x['count']),x['marker'],'Yes' if x['complete'] else 'No',str(x['final_current_status_count']),f"{x['final_sample_passed']}/{x['final_sample_count']}",f(x['all_route_traffic_verified_seconds'])])+' |')
lines+=['','All phase-level times and per-pass/grouped summaries are in [scale rows](data/scale-rows.json) and [scale summary](data/scale-summary.json). A failure for this route shape is not a universal bare-route limit. Full-route probes run only after every route has current status; a zero full-probe count can therefore mean not attempted. The sample and full probes check a shared generation marker through each hostname, not distinct backends or per-route unique response values. Marker strings are reused between scenarios, so a successful sample without current status is not proof of a fresh configuration generation. Attribute status, generated-configuration/API-size and traffic-propagation failures from their raw controller/API evidence.','', '### Recorded nonconvergence mechanisms', '', 'Each 1,000-route diagnostic captured a new Praxis pod rejecting `1003` filter entries against the compiled `100`-entry chain guard. In the three 5,000-route phases, replacement configurations contained '+large_counts_text+' entries; the controller also received timestamped API 422 errors because its generated ConfigMap exceeded 1,048,576 bytes. These are constraints of this generated configuration and filter-bearing route shape, not proof of a universal bare-route limit. Increasing pod memory would not alter either constraint.', '', 'The [attribution review](../evidence/qualification/final-facts/kubernetes-attribution.json) ties each diagnostic to a replacement pod created during that phase and restricts API errors to that phase’s timestamps. It also retains the six process-namespace collection gaps during these crashing scale scenarios; no HTTP measurement window has those gaps.', '', '## Graceful restart observations','', 'A separate probe schedules ten health requests/sec. The controller scenario rolls both controller replicas; the data-plane scenario deletes the sole gateway pod with normal Kubernetes termination. Reported recovery is the first sampled success after the last observed post-mutation failure, relative to mutation start. If no failure occurs, recovery latency is not inferred.','', '| Implementation | Pass | Mutation | Failed probes / total | Pre-mutation failures | Observed recovery seconds | Maximum dispatch delay seconds |','| --- | ---: | --- | ---: | ---: | ---: | ---: |']
for x in sorted(recovery,key=lambda x:(x['treatment'],x['pass'],x['kind'])):
 lines.append('| '+' | '.join([labels[x['treatment']],str(x['pass']),x['kind'],f"{x['failed_requests']}/{x['requests']}",str(x['pre_mutation_failures']),recovery_cell(x),f(x['max_dispatch_delay_seconds'])])+' |')
lines+=['', 'Across the three Praxis graceful-deletion windows, observed recovery after mutation is '+interval(next(x for x in recovery_summary if x['treatment']=='praxis-release' and x['kind']=='data-plane'),'observed_recovery_after_mutation_seconds')+' seconds. Agentgateway has no observed failure in these windows, so its recovery latency is not assigned zero.']
lines+=['','See [every recovery row](data/recovery-rows.json) and [three-pass summaries](data/recovery-summary.json). The HTTPX probes reuse connections. Graceful termination may overlap a draining pod and its replacement, and the window can end while the old process remains. These probes do not establish complete traffic handoff or fresh-connection availability. Steady-state HTTP tests separately enforce one stable pod before load. The observations are not an HA or hard-failure guarantee. Probe timing is quantized by the 100 ms schedule; command completion and traffic recovery are different events.','', '## Core nightly/operator compatibility','', 'All three current setup attempts preserve the stock operator configuration and exact nightly digest. The operator produces cluster name `gateway-backend~backend~8081`; core nightly rejects the `~` characters and exits 1. HTTP, scale and recovery behind this pairing are **not evaluated**. Do not label the dependent cases individual failures or record zero throughput. Standalone nightly forwarding is measured separately.','', '[Setup-block evidence](data/setup-blocks.json) retains image, process-exit, node readiness and generated-configuration details. The earlier expanded-conformance attempt also encountered empty-router startup incompatibility. No silent operator or data-plane patch was applied to improve either product’s score.','', '## Validity','', 'The [review]('+review_link+') approves this three-pass Kubernetes evidence family; standalone CPU profiles have separate measurements. It records 96 startup checks, 126 HTTP load cases, no load-tool/HTTP errors or resets, 23 Nighthawk requests in flight at cutoff, and unchanged installed inputs. The recurring Praxis controller restart counters predate HTTP; both controller processes remain stable during each HTTP window.','', 'The default-TCP and startup-drain Kubernetes pilots, image-switch qualification, and interrupted-fixture attempts are excluded in full. Only the corrected, reviewed three-pass campaign contributes to current performance/scale/recovery tables. See [methodology and exclusions](05-methodology-and-validity.md) and [reproduction](../docs/REPRODUCE.md).']
a.output.write_text('\n'.join(lines)+'\n');print(a.output)
